package net.imadz.codegen.scaffolding.cqrs.template.products

import net.imadz.codegen.scaffolding.cqrs.model.products._
import net.imadz.codegen.structure.NamingConventions

object ProductAdapterTemplate {
  def generate(model: ProductDomainModel): Vector[ProductSourceModel] = model.packages.toVector.sortBy(_._1).flatMap { case (context, pkg) =>
    val nodes = model.wire.filter(_.packageName == pkg); val pb = pkg + ".infrastructure.proto."
    def source(file: String, body: String, sources: Vector[net.imadz.meta.products.ProductSource]): ProductSourceModel =
      ProductSourceModel(NamingConventions.productPackagePath(pkg, "infrastructure/serialization/" + file), "// @generated by CodegenMain:semantic-products-1\n" + body, "serialization-adapter", sources.distinct, model.footprint)
    val serializer = "package " + pkg + ".infrastructure.serialization\n\nimport akka.serialization.SerializerWithStringManifest\nimport scalapb.GeneratedMessage\n\nfinal class DomainProtoSerializer extends SerializerWithStringManifest {\n" +
      "  override def identifier: Int = " + (741000 + model.layout.contexts.indexOf(context)) + "\n  override def manifest(value: AnyRef): String = value match {\n" +
      nodes.map(n => "    case _: " + pb + n.name + " => " + ujson.write(n.name) + "\n").mkString + "    case _ => throw new IllegalArgumentException(\"unregistered protobuf value\")\n  }\n" +
      "  override def toBinary(value: AnyRef): Array[Byte] = { manifest(value); value.asInstanceOf[GeneratedMessage].toByteArray }\n  override def fromBinary(bytes: Array[Byte], manifest: String): AnyRef = manifest match {\n" +
      nodes.map(n => "    case " + ujson.write(n.name) + " => " + pb + n.name + ".parseFrom(bytes)\n").mkString + "    case _ => throw new IllegalArgumentException(\"unknown protobuf manifest\")\n  }\n}\n"
    val legacy = source("DomainProtoSerializer.scala", serializer, nodes.flatMap(_.sources))
    // Keep every already-bounded legacy entry byte-identical, including its generated header.
    val serializerSources = if (legacy.content.length <= 65536) Vector(legacy) else {
      def partName(i: Int): String = NamingConventions.productSymbol("DomainProtoSerializerPart" + i)
      def partPath(i: Int): String = NamingConventions.productPackagePath(pkg, "infrastructure/serialization/" + partName(i) + ".scala")
      val protoPath = "app/protobuf/" + pkg.replace('.', '_') + "_domain.proto"
      def partSource(part: Vector[ProductWireNode], i: Int, hasNext: Boolean): ProductSourceModel = {
        val next = i + 1
        val body = "package " + pkg + ".infrastructure.serialization\n\ntrait " + partName(i) +
          (if (hasNext) " extends " + partName(next) else "") + " {\n" +
          "  protected def manifestPart" + i + "(value: AnyRef): String = value match {\n" +
          part.map(n => "    case _: " + pb + n.name + " => " + ujson.write(n.name) + "\n").mkString +
          "    case _ => " + (if (hasNext) "manifestPart" + next + "(value)" else "throw new IllegalArgumentException(\"unregistered protobuf value\")") + "\n  }\n" +
          "  protected def fromBinaryPart" + i + "(bytes: Array[Byte], manifest: String): AnyRef = manifest match {\n" +
          part.map(n => "    case " + ujson.write(n.name) + " => " + pb + n.name + ".parseFrom(bytes)\n").mkString +
          "    case _ => " + (if (hasNext) "fromBinaryPart" + next + "(bytes, manifest)" else "throw new IllegalArgumentException(\"unknown protobuf manifest\")") + "\n  }\n}\n"
        source(partName(i) + ".scala", body, part.flatMap(_.sources)).copy(
          dependencies = Vector(protoPath) ++ (if (hasNext) Vector(partPath(next)) else Vector.empty))
      }
      // Bound both JVM match methods and complete entries; long manifests/package names count too.
      def fits(part: Vector[ProductWireNode], i: Int): Boolean = part.size <= 128 &&
        math.max(partSource(part, i, true).content.length, partSource(part, i, false).content.length) <= 60000
      val parts = nodes.foldLeft(Vector.empty[Vector[ProductWireNode]]) { (parts, node) =>
        val i = math.max(0, parts.size - 1)
        val candidate = parts.lastOption.getOrElse(Vector.empty) :+ node
        if (fits(candidate, i)) {
          if (parts.isEmpty) Vector(candidate) else parts.init :+ candidate
        } else {
          require(fits(Vector(node), parts.size), "protobuf serializer case exceeds bounded source entry")
          parts :+ Vector(node)
        }
      }
      val facade = "package " + pkg + ".infrastructure.serialization\n\nimport akka.serialization.SerializerWithStringManifest\nimport scalapb.GeneratedMessage\n\nfinal class DomainProtoSerializer extends SerializerWithStringManifest with " + partName(0) + " {\n" +
        "  override def identifier: Int = " + (741000 + model.layout.contexts.indexOf(context)) + "\n" +
        "  override def manifest(value: AnyRef): String = manifestPart0(value)\n" +
        "  override def toBinary(value: AnyRef): Array[Byte] = { manifest(value); value.asInstanceOf[GeneratedMessage].toByteArray }\n" +
        "  override def fromBinary(bytes: Array[Byte], manifest: String): AnyRef = fromBinaryPart0(bytes, manifest)\n}\n"
      val facadeSource = source("DomainProtoSerializer.scala", facade, nodes.flatMap(_.sources)).copy(dependencies = Vector(partPath(0)))
      require(facadeSource.content.length <= 60000, "protobuf serializer facade exceeds bounded source entry")
      Vector(facadeSource) ++ parts.zipWithIndex.map { case (part, i) => partSource(part, i, i + 1 < parts.size) }
    }
    serializerSources ++ model.aggregates.filter(_.declaration.ref.context == context).map { a =>
      val id = a.declaration.ref.id; val name = NamingConventions.productSymbol(id)
      val adapter = "package " + pkg + ".infrastructure.serialization\n\nimport akka.persistence.typed.{EventAdapter, EventSeq, SnapshotAdapter}\nimport " + pkg + ".domain._\nimport " + pkg + ".domain." + name + "Protocol._\n\nobject " + name + "EventAdapter extends EventAdapter[Event, scalapb.GeneratedMessage] {\n" +
        "  override def manifest(event: Event): String = event match {\n" + a.events.map(e => "    case _: " + NamingConventions.productSymbol(e.event.id) + " => " + ujson.write(id + e.event.id + "PB") + "\n").mkString + "  }\n" +
        "  override def toJournal(event: Event): scalapb.GeneratedMessage = event match {\n" + a.events.map(e => "    case value: " + NamingConventions.productSymbol(e.event.id) + " => DomainConverters.encode" + id + e.event.id + "PB(value)\n").mkString + "  }\n" +
        "  override def fromJournal(event: scalapb.GeneratedMessage, manifest: String): EventSeq[Event] = (event, manifest) match {\n" +
        a.events.map(e => "    case (value: " + pb + id + e.event.id + "PB, " + ujson.write(id + e.event.id + "PB") + ") => EventSeq.single(DomainConverters.decode" + id + e.event.id + "PB(value))\n").mkString +
        "    case _ => throw new IllegalArgumentException(\"event manifest and payload mismatch\")\n  }\n}\nobject " + name + "SnapshotAdapter extends SnapshotAdapter[" + name + "State] {\n" +
        "  override def toJournal(state: " + name + "State): Any = DomainConverters.encode" + id + "StatePB(state)\n  override def fromJournal(value: Any): " + name + "State = value match {\n" +
        "    case state: " + pb + id + "StatePB => DomainConverters.decode" + id + "StatePB(state)\n    case _ => throw new IllegalArgumentException(\"snapshot type mismatch\")\n  }\n}\n"
      source(id + "Adapters.scala", adapter, Vector(a.declaration.source) ++ a.events.map(_.source))
    }
  }
}
